  const requiredCovered=Math.max(0,product.peopleCovered-1),coveredNames=Array.isArray(body.coveredPeople)?body.coveredPeople.map((name:unknown)=>clean(name,200)).filter(Boolean).slice(0,requiredCovered):[];if(coveredNames.length!==requiredCovered)throw new Error(`Add all ${product.peopleCovered} people covered by this membership`)
